  gap: 8px;
}
.carousel-btn {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  border: 1px solid var(--color-border);
  background: var(--color-bg-alt);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition);
  color: var(--color-text);
}
.carousel-btn:hover { background: var(--color-text); color: #fff; border-color: var(--color-text); }
.carousel-btn:disabled { opacity: 0.3; cursor: not-allowed; }
.carousel-btn svg { width: 16px; height: 16px; }

.carousel-track-wrapper {
  overflow: hidden;
  margin: 0 -16px;
  padding: 0 16px;
}
.carousel-track {
  display: flex;
  gap: var(--spacing-md);
  overflow-x: auto;
  scroll-behavior: smooth;
  scrollbar-width: none;
  -ms-overflow-style: none;
  padding-bottom: var(--spacing-sm);
}
.carousel-track::-webkit-scrollbar { display: none; }

/* Product Card */
.product-card {
  flex: 0 0 260px;
  background: var(--color-bg-alt);
  border-radius: var(--border-radius);
  padding: var(--spacing-md);
  display: flex;
  flex-direction: column;
  text-align: center;
}
.product-card-image {
  width: 100%;
  height: 140px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 60px;
  margin-bottom: var(--spacing-sm);
}
.product-card-badge {
  display: inline-block;
  background: #ff4136;
  color: #fff;
  font-size: 11px;
  font-weight: 600;
  padding: 3px 8px;
  border-radius: 10px;
  text-transform: uppercase;
  margin-bottom: var(--spacing-xs);
}
.product-card-title {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: 4px;
}
.product-card-tagline {
  font-size: 13px;
  color: var(--color-text-secondary);
  margin-bottom: var(--spacing-sm);
}
.product-card-price {
  font-size: 15px;
  font-weight: 500;
  margin-bottom: 2px;
}
.product-card-monthly {
  font-size: 13px;
  color: var(--color-text-secondary);
  margin-bottom: var(--spacing-sm);
}
.product-card-actions { margin-top: auto; padding-top: var(--spacing-sm); }

/* Help Card */
.help-card {
  flex: 0 0 280px;
  background: var(--color-bg-alt);
  border-radius: var(--border-radius);
  padding: var(--spacing-lg);
  text-align: center;
}
.help-card-icon { font-size: 48px; margin-bottom: var(--spacing-sm); }
.help-card-title { font-size: 19px; font-weight: 600; margin-bottom: var(--spacing-xs); }
.help-card-desc { font-size: 14px; color: var(--color-text-secondary); }

/* Difference Card */
.diff-card {
  flex: 0 0 240px;
  background: var(--color-bg-alt);
  border-radius: var(--border-radius);
  padding: var(--spacing-md);
  text-align: center;
}
.diff-card-icon { font-size: 40px; margin-bottom: var(--spacing-sm); }
.diff-card-title { font-size: 17px; font-weight: 600; margin-bottom: var(--spacing-xs); }
.diff-card-desc { font-size: 13px; color: var(--color-text-secondary); }

/* Savings Card */
.savings-card {
  flex: 0 0 300px;
  background: var(--color-bg-alt);
  border-radius: var(--border-radius);
  padding: var(--spacing-lg);
  display: flex;
  flex-direction: column;
}
.savings-card-title { font-size: 19px; font-weight: 600; margin-bottom: var(--spacing-xs); }
.savings-card-desc { font-size: 14px; color: var(--color-text-secondary); margin-bottom: var(--spacing-md); flex-grow: 1; }

/* Guide Card */
.guide-card {
  flex: 0 0 260px;
  background: var(--color-bg-alt);
  border-radius: var(--border-radius);
  padding: var(--spacing-lg);
  text-align: center;
}
.guide-card-icon { font-size: 48px; margin-bottom: var(--spacing-sm); }
.guide-card-title { font-size: 17px; font-weight: 600; margin-bottom: var(--spacing-xs); }
.guide-card-desc { font-size: 14px; color: var(--color-text-secondary); }

/* Tabs */
.tabs { display: flex; gap: var(--spacing-md); margin-bottom: var(--spacing-md); border-bottom: 1px solid var(--color-border); }
.tab {
  font-size: 15px;
  color: var(--color-text-secondary);
  padding: var(--spacing-sm) 0;
  border-bottom: 2px solid transparent;
  cursor: pointer;
  transition: all var(--transition);
  background: none;
  border-top: none;
  border-left: none;
  border-right: none;
  font-family: inherit;
}
.tab:hover { color: var(--color-text); }
.tab.active { color: var(--color-accent); border-bottom-color: var(--color-accent); }

.tab-content { display: none; }
.tab-content.active { display: block; }

/* Entertainment Cards */
.ent-card {
  flex: 0 0 280px;
  background: var(--color-bg-alt);
  border-radius: var(--border-radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
}
.ent-card-image {
  height: 160px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 60px;
  color: #fff;
}
.ent-card-body { padding: var(--spacing-md); flex-grow: 1; display: flex; flex-direction: column; }
.ent-card-title { font-size: 17px; font-weight: 600; margin-bottom: 4px; }
.ent-card-desc { font-size: 14px; color: var(--color-text-secondary); margin-bottom: var(--spacing-sm); flex-grow: 1; }

/* Icon Bar */
.icon-bar {
  display: flex;
  justify-content: center;
  gap: var(--spacing-lg);
  flex-wrap: wrap;
  padding: var(--spacing-lg) 0;
}
.icon-bar-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--spacing-xs);
  color: var(--color-text);
  text-decoration: none;
}
.icon-bar-item:hover { text-decoration: none; color: var(--color-accent); }
.icon-bar-item span { font-size: 13px; font-weight: 500; }
.icon-bar-icon { font-size: 40px; }

/* Hero (Store) */
.store-hero {
  background: var(--color-bg-alt);
  text-align: center;
  padding: var(--spacing-xl) var(--spacing-md);
}
.store-hero h1 { font-size: 56px; font-weight: 600; letter-spacing: -0.5px; margin-bottom: var(--spacing-xs); }
.store-hero p { font-size: 22px; color: var(--color-text-secondary); margin-bottom: var(--spacing-lg); }
.store-hero-actions { display: flex; gap: var(--spacing-sm); justify-content: center; flex-wrap: wrap; }

/* Category Hero */
.category-hero {
  background: var(--color-bg-alt);
  text-align: center;
  padding: var(--spacing-xl) var(--spacing-md);
}
.category-hero h1 { font-size: 48px; font-weight: 600; letter-spacing: -0.5px; margin-bottom: var(--spacing-xs); }
.category-hero p { font-size: 20px; color: var(--color-text-secondary); }

/* Quick Links */
.quick-links {
  display: flex;
  justify-content: center;
  gap: var(--spacing-md);
  flex-wrap: wrap;
  padding: var(--spacing-lg) 0;
}
.quick-link {
  padding: 12px 24px;
  background: var(--color-bg-alt);
  border-radius: 24px;
  font-size: 14px;
  font-weight: 500;
  color: var(--color-accent);
  border: 1px solid var(--color-border);
  transition: all var(--transition);
}
.quick-link:hover { background: var(--color-accent); color: #fff; border-color: var(--color-accent); text-decoration: none; }

/* Footer */
.footer {
  background: var(--color-bg-alt);
  border-top: 1px solid var(--color-border);
  padding: var(--spacing-lg) 0 var(--spacing-xl);
}
.footer-inner { max-width: var(--max-width); margin: 0 auto; padding: 0 var(--spacing-md); }
.footer-columns {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: var(--spacing-lg);
}
@media (max-width: 768px) {
  .footer-columns { grid-template-columns: repeat(2, 1fr); }
  .product-grid { grid-template-columns: 1fr; }
  .section-title { font-size: 32px; }
  .store-hero h1 { font-size: 40px; }
  .carousel-header h2 { font-size: 24px; }
}
.footer-col-title {
  font-size: 12px;
  font-weight: 600;
  color: var(--color-text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: var(--spacing-sm);
}
.footer-links { list-style: none; }
.footer-links li { margin-bottom: 6px; }
.footer-links a { font-size: 14px; color: var(--color-text-secondary); }
.footer-links a:hover { color: var(--color-text); text-decoration: none; }

.footer-accordion { display: none; }
@media (max-width: 768px) {
  .footer-desktop { display: none; }
  .footer-accordion { display: block; }
  .footer-accordion-item { border-bottom: 1px solid var(--color-border); }
  .footer-accordion-title {
    font-size: 14px;
    font-weight: 600;
    color: var(--color-text);
    padding: var(--spacing-sm) 0;
    cursor: pointer;
    display: flex;
    justify-content: space-between;
    align-items: center;
  }
  .footer-accordion-title::after { content: "+"; font-size: 18px; }
  .footer-accordion-item.open .footer-accordion-title::after { content: "−"; }
  .footer-accordion-content { display: none; padding-bottom: var(--spacing-sm); }
  .footer-accordion-item.open .footer-accordion-content { display: block; }
  .footer-accordion-content a { font-size: 14px; color: var(--color-text-secondary); display: block; padding: 4px 0; }
}

.footer-bottom {
  margin-top: var(--spacing-lg);
  padding-top: var(--spacing-md);
  border-top: 1px solid var(--color-border);
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--spacing-sm);
}
.footer-copyright { font-size: 13px; color: var(--color-text-secondary); }
.footer-legal { font-size: 12px; color: var(--color-text-secondary); max-width: 600px; }

/* Promo Banner */
.promo-banner {
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  color: #fff;
  text-align: center;
  padding: var(--spacing-lg);
  border-radius: var(--border-radius);
  margin: var(--spacing-lg) 0;
}
.promo-banner h3 { font-size: 24px; font-weight: 600; margin-bottom: var(--spacing-xs); }

/* Experience Section */
.experience-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--spacing-md);
}
@media (max-width: 768px) {
  .experience-grid { grid-template-columns: 1fr; }
}
.experience-card {
  background: var(--color-bg-alt);
  border-radius: var(--border-radius);
  padding: var(--spacing-lg);
  text-align: center;
}
.experience-card-icon { font-size: 48px; margin-bottom: var(--spacing-sm); }
.experience-card-title { font-size: 19px; font-weight: 600; margin-bottom: var(--spacing-xs); }
.experience-card-desc { font-size: 14px; color: var(--color-text-secondary); }

/* Brand Collab */
.collab-banner {
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%);
  color: #fff;
  border-radius: var(--border-radius);
  padding: var(--spacing-xl);
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: var(--spacing-lg);
}
.collab-content h3 { font-size: 32px; font-weight: 600; margin-bottom: var(--spacing-xs); }
.collab-content p { font-size: 18px; opacity: 0.8; }

/* Ways to Save */
.ways-to-save-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: var(--spacing-md);
}
@media (max-width: 900px) { .ways-to-save-grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 500px) { .ways-to-save-grid { grid-template-columns: 1fr; } }

.way-to-save-card {
  background: var(--color-bg-alt);
  border-radius: var(--border-radius);
  padding: var(--spacing-md);
}
.way-to-save-card-icon { font-size: 36px; margin-bottom: var(--spacing-sm); }
.way-to-save-card-title { font-size: 15px; font-weight: 600; margin-bottom: 4px; }
.way-to-save-card-desc { font-size: 13px; color: var(--color-text-secondary); }

/* Section IDs for smooth scroll */
.section-id { scroll-margin-top: 100px; }

/* Grids */
.two-col-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--spacing-md);
}
@media (max-width: 768px) { .two-col-grid { grid-template-columns: 1fr; } }

/* Accessory Card */
.accessory-card {
  flex: 0 0 220px;
  background: var(--color-bg-alt);
  border-radius: var(--border-radius);
  padding: var(--spacing-md);
  text-align: center;
}
.accessory-card-image {
  width: 100%;
  height: 120px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 60px;
  margin-bottom: var(--spacing-sm);
}
.accessory-card-title { font-size: 14px; font-weight: 600; margin-bottom: 4px; }
.accessory-card-price { font-size: 14px; color: var(--color-text-secondary); }

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --color-bg: #f5f5f7;
  --color-bg-alt: #ffffff;
  --color-text: #1d1d1f;
  --color-text-secondary: #6e6e73;
  --color-accent: #0066cc;
  --color-accent-hover: #0055aa;
  --color-border: #d2d2d7;
  --font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "SF Pro Display", "Helvetica Neue", Helvetica, Arial, sans-serif;
  --max-width: 1200px;
  --spacing-xs: 8px;
  --spacing-sm: 16px;
  --spacing-md: 24px;
  --spacing-lg: 48px;
  --spacing-xl: 80px;
  --border-radius: 12px;
  --border-radius-sm: 8px;
  --shadow-card: 0 2px 12px rgba(0,0,0,0.08);
  --transition: 0.2s ease;
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-family);
  background: var(--color-bg);
  color: var(--color-text);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

a { color: var(--color-accent); text-decoration: none; }
a:hover { text-decoration: underline; }

img { max-width: 100%; display: block; }

/* Navigation */
.nav {
  background: var(--color-bg-alt);
  border-bottom: 1px solid var(--color-border);
  position: sticky;
  top: 0;
  z-index: 100;
}
.nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--spacing-md);
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 52px;
}
.nav-logo {
  font-size: 21px;
  font-weight: 600;
  color: var(--color-text);
  letter-spacing: -0.5px;
}
.nav-links { display: flex; gap: var(--spacing-md); list-style: none; }
.nav-links a {
  font-size: 14px;
  color: var(--color-text-secondary);
  transition: color var(--transition);
}
.nav-links a:hover { color: var(--color-text); text-decoration: none; }

/* Section Nav (category pages) */
.section-nav {
  background: var(--color-bg-alt);
  border-bottom: 1px solid var(--color-border);
  position: sticky;
  top: 52px;
  z-index: 99;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}
.section-nav::-webkit-scrollbar { display: none; }
.section-nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--spacing-md);
  display: flex;
  gap: var(--spacing-lg);
  white-space: nowrap;
}
.section-nav a {
  font-size: 14px;
  color: var(--color-text-secondary);
  padding: var(--spacing-sm) 0;
  display: inline-block;
  border-bottom: 2px solid transparent;
  transition: all var(--transition);
}
.section-nav a:hover, .section-nav a.active {
  color: var(--color-accent);
  border-bottom-color: var(--color-accent);
  text-decoration: none;
}

/* Container */
.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--spacing-md);
}

/* Section */
.section { padding: var(--spacing-xl) 0; }
.section-title {
  font-size: 40px;
  font-weight: 600;
  letter-spacing: -0.5px;
  margin-bottom: var(--spacing-xs);
}
.section-subtitle {
  font-size: 18px;
  color: var(--color-text-secondary);
  margin-bottom: var(--spacing-lg);
}

/* Ribbon Banner */
.ribbon-banner {
  background: var(--color-text);
  color: var(--color-bg);
  text-align: center;
  padding: var(--spacing-sm);
  font-size: 14px;
}
.ribbon-banner a { color: #fff; }

/* Product Grid (Homepage) */
.product-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--spacing-sm);
}
@media (min-width: 768px) {
  .product-grid { grid-template-columns: repeat(3, 1fr); gap: var(--spacing-md); }
}
.product-tile {
  background: var(--color-bg-alt);
  border-radius: var(--border-radius);
  padding: var(--spacing-lg);
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  min-height: 380px;
  position: relative;
  overflow: hidden;
}
.product-tile-badge {
  position: absolute;
  top: var(--spacing-sm);
  left: var(--spacing-sm);
  background: #ff4136;
  color: #fff;
  font-size: 12px;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 20px;
  text-transform: uppercase;
}
.product-tile-image {
  width: 160px;
  height: 160px;
  margin: var(--spacing-md) 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 80px;
}
.product-tile-title {
  font-size: 28px;
  font-weight: 600;
  margin-bottom: 4px;
}
.product-tile-tagline {
  font-size: 15px;
  color: var(--color-text-secondary);
  margin-bottom: var(--spacing-md);
}
.product-tile-actions { display: flex; gap: var(--spacing-sm); margin-top: auto; }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 10px 20px;
  border-radius: 24px;
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  transition: all var(--transition);
  border: none;
  min-width: 100px;
}
.btn-primary {
  background: var(--color-accent);
  color: #fff;
}
.btn-primary:hover { background: var(--color-accent-hover); text-decoration: none; }
.btn-secondary {
  background: transparent;
  color: var(--color-accent);
  border: 1px solid var(--color-accent);
}
.btn-secondary:hover { background: var(--color-accent); color: #fff; text-decoration: none; }

/* Carousel */
.carousel-section { position: relative; }
.carousel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--spacing-md);
}
.carousel-header h2 { font-size: 32px; font-weight: 600; }
.carousel-nav {
  display: flex;
  gap: 8px;
}
.carousel-btn {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  border: 1px solid var(--color-border);
  background: var(--color-bg-alt);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition);
  color: var(--color-text);
}
.carousel-btn:hover { background: var(--color-text); color: #fff; border-color: var(--color-text); }
.carousel-btn:disabled { opacity: 0.3; cursor: not-allowed; }
.carousel-btn svg { width: 16px; height: 16px; }

.carousel-track-wrapper {
  overflow: hidden;
  margin: 0 -16px;
  padding: 0 16px;
}
.carousel-track {
  display: flex;
  gap: var(--spacing-md);
  overflow-x: auto;
  scroll-behavior: smooth;
  scrollbar-width: none;
  -ms-overflow-style: none;
  padding-bottom: var(--spacing-sm);
}
.carousel-track::-webkit-scrollbar { display: none; }

/* Product Card */
.product-card {
  flex: 0 0 260px;
  background: var(--color-bg-alt);
  border-radius: var(--border-radius);
  padding: var(--spacing-md);
  display: flex;
  flex-direction: column;
  text-align: center;
}
.product-card-image {
  width: 100%;
  height: 140px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 60px;
  margin-bottom: var(--spacing-sm);
}
.product-card-badge {
  display: inline-block;
  background: #ff4136;
  color: #fff;
  font-size: 11px;
  font-weight: 600;
  padding: 3px 8px;
  border-radius: 10px;
  text-transform: uppercase;
  margin-bottom: var(--spacing-xs);
}
.product-card-title {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: 4px;
}
.product-card-tagline {
  font-size: 13px;
  color: var(--color-text-secondary);
  margin-bottom: var(--spacing-sm);
}
.product-card-price {
  font-size: 15px;
  font-weight: 500;
  margin-bottom: 2px;
}
.product-card-monthly {
  font-size: 13px;
  color: var(--color-text-secondary);
  margin-bottom: var(--spacing-sm);
}
.product-card-actions { margin-top: auto; padding-top: var(--spacing-sm); }

/* Help Card */
.help-card {
  flex: 0 0 280px;
  background: var(--color-bg-alt);
  border-radius: var(--border-radius);
  padding: var(--spacing-lg);
  text-align: center;
}
.help-card-icon { font-size: 48px; margin-bottom: var(--spacing-sm); }
.help-card-title { font-size: 19px; font-weight: 600; margin-bottom: var(--spacing-xs); }
.help-card-desc { font-size: 14px; color: var(--color-text-secondary); }

/* Difference Card */
.diff-card {
  flex: 0 0 240px;
  background: var(--color-bg-alt);
  border-radius: var(--border-radius);
  padding: var(--spacing-md);
  text-align: center;
}
.diff-card-icon { font-size: 40px; margin-bottom: var(--spacing-sm); }
.diff-card-title { font-size: 17px; font-weight: 600; margin-bottom: var(--spacing-xs); }
.diff-card-desc { font-size: 13px; color: var(--color-text-secondary); }

/* Savings Card */
.savings-card {
  flex: 0 0 300px;
  background: var(--color-bg-alt);
  border-radius: var(--border-radius);
  padding: var(--spacing-lg);
  display: flex;
  flex-direction: column;
}
.savings-card-title { font-size: 19px; font-weight: 600; margin-bottom: var(--spacing-xs); }
.savings-card-desc { font-size: 14px; color: var(--color-text-secondary); margin-bottom: var(--spacing-md); flex-grow: 1; }

/* Guide Card */
.guide-card {
  flex: 0 0 260px;
  background: var(--color-bg-alt);
  border-radius: var(--border-radius);
  padding: var(--spacing-lg);
  text-align: center;
}
.guide-card-icon { font-size: 48px; margin-bottom: var(--spacing-sm); }
.guide-card-title { font-size: 17px; font-weight: 600; margin-bottom: var(--spacing-xs); }
.guide-card-desc { font-size: 14px; color: var(--color-text-secondary); }

/* Tabs */
.tabs { display: flex; gap: var(--spacing-md); margin-bottom: var(--spacing-md); border-bottom: 1px solid var(--color-border); }
.tab {
  font-size: 15px;
  color: var(--color-text-secondary);
  padding: var(--spacing-sm) 0;
  border-bottom: 2px solid transparent;
  cursor: pointer;
  transition: all var(--transition);
  background: none;
  border-top: none;
  border-left: none;
  border-right: none;
  font-family: inherit;
}
.tab:hover { color: var(--color-text); }
.tab.active { color: var(--color-accent); border-bottom-color: var(--color-accent); }

.tab-content { display: none; }
.tab-content.active { display: block; }

/* Entertainment Cards */
.ent-card {
  flex: 0 0 280px;
  background: var(--color-bg-alt);
  border-radius: var(--border-radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
}
.ent-card-image {
  height: 160px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 60px;
  color: #fff;
}
.ent-card-body { padding: var(--spacing-md); flex-grow: 1; display: flex; flex-direction: column; }
.ent-card-title { font-size: 17px; font-weight: 600; margin-bottom: 4px; }
.ent-card-desc { font-size: 14px; color: var(--color-text-secondary); margin-bottom: var(--spacing-sm); flex-grow: 1; }

/* Icon Bar */
.icon-bar {
  display: flex;
  justify-content: center;
  gap: var(--spacing-lg);
  flex-wrap: wrap;
  padding: var(--spacing-lg) 0;
}
.icon-bar-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--spacing-xs);
  color: var(--color-text);
  text-decoration: none;
}
.icon-bar-item:hover { text-decoration: none; color: var(--color-accent); }
.icon-bar-item span { font-size: 13px; font-weight: 500; }
.icon-bar-icon { font-size: 40px; }

/* Hero (Store) */
.store-hero {
  background: var(--color-bg-alt);
  text-align: center;
  padding: var(--spacing-xl) var(--spacing-md);
}
.store-hero h1 { font-size: 56px; font-weight: 600; letter-spacing: -0.5px; margin-bottom: var(--spacing-xs); }
.store-hero p { font-size: 22px; color: var(--color-text-secondary); margin-bottom: var(--spacing-lg); }
.store-hero-actions { display: flex; gap: var(--spacing-sm); justify-content: center; flex-wrap: wrap; }

/* Category Hero */
.category-hero {
  background: var(--color-bg-alt);
  text-align: center;
  padding: var(--spacing-xl) var(--spacing-md);
}
.category-hero h1 { font-size: 48px; font-weight: 600; letter-spacing: -0.5px; margin-bottom: var(--spacing-xs); }
.category-hero p { font-size: 20px; color: var(--color-text-secondary); }

/* Quick Links */
.quick-links {
  display: flex;
  justify-content: center;
  gap: var(--spacing-md);
  flex-wrap: wrap;
  padding: var(--spacing-lg) 0;
}
.quick-link {
  padding: 12px 24px;
  background: var(--color-bg-alt);
  border-radius: 24px;
  font-size: 14px;
  font-weight: 500;
  color: var(--color-accent);
  border: 1px solid var(--color-border);
  transition: all var(--transition);
}
.quick-link:hover { background: var(--color-accent); color: #fff; border-color: var(--color-accent); text-decoration: none; }

/* Footer */
.footer {
  background: var(--color-bg-alt);
  border-top: 1px solid var(--color-border);
  padding: var(--spacing-lg) 0 var(--spacing-xl);
}
.footer-inner { max-width: var(--max-width); margin: 0 auto; padding: 0 var(--spacing-md); }
.footer-columns {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: var(--spacing-lg);
}
@media (max-width: 768px) {
  .footer-columns { grid-template-columns: repeat(2, 1fr); }
  .product-grid { grid-template-columns: 1fr; }
  .section-title { font-size: 32px; }
  .store-hero h1 { font-size: 40px; }
  .carousel-header h2 { font-size: 24px; }
}
.footer-col-title {
  font-size: 12px;
  font-weight: 600;
  color: var(--color-text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: var(--spacing-sm);
}
.footer-links { list-style: none; }
.footer-links li { margin-bottom: 6px; }
.footer-links a { font-size: 14px; color: var(--color-text-secondary); }
.footer-links a:hover { color: var(--color-text); text-decoration: none; }

.footer-accordion { display: none; }
@media (max-width: 768px) {
  .footer-desktop { display: none; }
  .footer-accordion { display: block; }
  .footer-accordion-item { border-bottom: 1px solid var(--color-border); }
  .footer-accordion-title {
    font-size: 14px;
    font-weight: 600;
    color: var(--color-text);
    padding: var(--spacing-sm) 0;
    cursor: pointer;
    display: flex;
    justify-content: space-between;
    align-items: center;
  }
  .footer-accordion-title::after { content: "+"; font-size: 18px; }
  .footer-accordion-item.open .footer-accordion-title::after { content: "−"; }
  .footer-accordion-content { display: none; padding-bottom: var(--spacing-sm); }
  .footer-accordion-item.open .footer-accordion-content { display: block; }
  .footer-accordion-content a { font-size: 14px; color: var(--color-text-secondary); display: block; padding: 4px 0; }
}

.footer-bottom {
  margin-top: var(--spacing-lg);
  padding-top: var(--spacing-md);
  border-top: 1px solid var(--color-border);
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--spacing-sm);
}
.footer-copyright { font-size: 13px; color: var(--color-text-secondary); }
.footer-legal { font-size: 12px; color: var(--color-text-secondary); max-width: 600px; }

/* Promo Banner */
.promo-banner {
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  color: #fff;
  text-align: center;
  padding: var(--spacing-lg);
  border-radius: var(--border-radius);
  margin: var(--spacing-lg) 0;
}
.promo-banner h3 { font-size: 24px; font-weight: 600; margin-bottom: var(--spacing-xs); }

/* Experience Section */
.experience-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--spacing-md);
}
@media (max-width: 768px) {
  .experience-grid { grid-template-columns: 1fr; }
}
.experience-card {
  background: var(--color-bg-alt);
  border-radius: var(--border-radius);
  padding: var(--spacing-lg);
  text-align: center;
}
.experience-card-icon { font-size: 48px; margin-bottom: var(--spacing-sm); }
.experience-card-title { font-size: 19px; font-weight: 600; margin-bottom: var(--spacing-xs); }
.experience-card-desc { font-size: 14px; color: var(--color-text-secondary); }

/* Brand Collab */
.collab-banner {
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%);
  color: #fff;
  border-radius: var(--border-radius);
  padding: var(--spacing-xl);
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: var(--spacing-lg);
}
.collab-content h3 { font-size: 32px; font-weight: 600; margin-bottom: var(--spacing-xs); }
.collab-content p { font-size: 18px; opacity: 0.8; }

/* Ways to Save */
.ways-to-save-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: var(--spacing-md);
}
@media (max-width: 900px) { .ways-to-save-grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 500px) { .ways-to-save-grid { grid-template-columns: 1fr; } }

.way-to-save-card {
  background: var(--color-bg-alt);
  border-radius: var(--border-radius);
  padding: var(--spacing-md);
}
.way-to-save-card-icon { font-size: 36px; margin-bottom: var(--spacing-sm); }
.way-to-save-card-title { font-size: 15px; font-weight: 600; margin-bottom: 4px; }
.way-to-save-card-desc { font-size: 13px; color: var(--color-text-secondary); }

/* Section IDs for smooth scroll */
.section-id { scroll-margin-top: 100px; }

/* Grids */
.two-col-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--spacing-md);
}
@media (max-width: 768px) { .two-col-grid { grid-template-columns: 1fr; } }

/* Accessory Card */
.accessory-card {
  flex: 0 0 220px;
  background: var(--color-bg-alt);
  border-radius: var(--border-radius);
  padding: var(--spacing-md);
  text-align: center;
}
.accessory-card-image {
  width: 100%;
  height: 120px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 60px;
  margin-bottom: var(--spacing-sm);
}
.accessory-card-title { font-size: 14px; font-weight: 600; margin-bottom: 4px; }
.accessory-card-price { font-size: 14px; color: var(--color-text-secondary); }

raw_arguments.content:
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --color-bg: #f5f5f7;
  --color-bg-alt: #ffffff;
  --color-text: #1d1d1f;
  --color-text-secondary: #6e6e73;
  --color-accent: #0066cc;
  --color-accent-hover: #0055aa;
  --color-border: #d2d2d7;
  --font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "SF Pro Display", "Helvetica Neue", Helvetica, Arial, sans-serif;
  --max-width: 1200px;
  --spacing-xs: 8px;
  --spacing-sm: 16px;
  --spacing-md: 24px;
  --spacing-lg: 48px;
  --spacing-xl: 80px;
  --border-radius: 12px;
  --border-radius-sm: 8px;
  --shadow-card: 0 2px 12px rgba(0,0,0,0.08);
  --transition: 0.2s ease;
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-family);
  background: var(--color-bg);
  color: var(--color-text);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

a { color: var(--color-accent); text-decoration: none; }
a:hover { text-decoration: underline; }

img { max-width: 100%; display: block; }

/* Navigation */
.nav {
  background: var(--color-bg-alt);
  border-bottom: 1px solid var(--color-border);
  position: sticky;
  top: 0;
  z-index: 100;
}
.nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--spacing-md);
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 52px;
}
.nav-logo {
  font-size: 21px;
  font-weight: 600;
  color: var(--color-text);
  letter-spacing: -0.5px;
}
.nav-links { display: flex; gap: var(--spacing-md); list-style: none; }
.nav-links a {
  font-size: 14px;
  color: var(--color-text-secondary);
  transition: color var(--transition);
}
.nav-links a:hover { color: var(--color-text); text-decoration: none; }

/* Section Nav (category pages) */
.section-nav {
  background: var(--color-bg-alt);
  border-bottom: 1px solid var(--color-border);
  position: sticky;
  top: 52px;
  z-index: 99;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}
.section-nav::-webkit-scrollbar { display: none; }
.section-nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--spacing-md);
  display: flex;
  gap: var(--spacing-lg);
  white-space: nowrap;
}
.section-nav a {
  font-size: 14px;
  color: var(--color-text-secondary);
  padding: var(--spacing-sm) 0;
  display: inline-block;
  border-bottom: 2px solid transparent;
  transition: all var(--transition);
}
.section-nav a:hover, .section-nav a.active {
  color: var(--color-accent);
  border-bottom-color: var(--color-accent);
  text-decoration: none;
}

/* Container */
.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--spacing-md);
}

/* Section */
.section { padding: var(--spacing-xl) 0; }
.section-title {
  font-size: 40px;
  font-weight: 600;
  letter-spacing: -0.5px;
  margin-bottom: var(--spacing-xs);
}
.section-subtitle {
  font-size: 18px;
  color: var(--color-text-secondary);
  margin-bottom: var(--spacing-lg);
}

/* Ribbon Banner */
.ribbon-banner {
  background: var(--color-text);
  color: var(--color-bg);
  text-align: center;
  padding: var(--spacing-sm);
